import React, { useState, useEffect } from 'react';
import { Menu, X } from 'lucide-react';

export const Navbar: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <nav className={`fixed top-0 left-0 w-full z-50 transition-all duration-300 ${isScrolled ? 'bg-brand-dark/95 backdrop-blur-md border-b border-white/10 py-4' : 'bg-transparent py-6'}`}>
      <div className="container mx-auto px-6 flex justify-between items-center">

        {/* Logo */}
        <a href="#home" className="flex flex-col group">
          <span className={`font-serif text-2xl font-bold tracking-wider transition-colors ${isScrolled ? 'text-white' : 'text-brand-paper'}`}>
            ARKA <span className="text-brand-accent">ORIGINALS</span>
          </span>
        </a>

        {/* Desktop Links */}
        <div className="hidden md:flex items-center gap-8">
          <a href="#legacy" className="text-sm uppercase tracking-widest text-white/80 hover:text-brand-accent transition-colors">Legacy</a>
          <a href="#products" className="text-sm uppercase tracking-widest text-white/80 hover:text-brand-accent transition-colors">Products</a>
          <a href="#contact" className="px-6 py-2 border border-brand-accent text-brand-accent text-sm uppercase tracking-widest font-bold hover:bg-brand-accent hover:text-black transition-all">
            Contact
          </a>
        </div>

        {/* Mobile Toggle */}
        <button 
          className="md:hidden text-white"
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        >
          {isMobileMenuOpen ? <X /> : <Menu />}
        </button>
      </div>

      {/* Mobile Menu */}
      {isMobileMenuOpen && (
        <div className="md:hidden absolute top-full left-0 w-full bg-brand-dark border-b border-white/10 p-6 flex flex-col gap-6 items-center shadow-2xl">
          <a onClick={() => setIsMobileMenuOpen(false)} href="#legacy" className="text-sm uppercase tracking-widest text-white/80">Legacy</a>
          <a onClick={() => setIsMobileMenuOpen(false)} href="#products" className="text-sm uppercase tracking-widest text-white/80">Products</a>
          <a onClick={() => setIsMobileMenuOpen(false)} href="#contact" className="text-brand-accent text-sm uppercase tracking-widest font-bold">Contact Us</a>
        </div>
      )}
    </nav>
  );
};

