// This service handles data persistence.
// Ideally, this should connect to your own backend (Node/Python/etc).
// For this serverless demo, we use JSONBlob.com to store data in the cloud.

// TODO: AFTER CLICKING "INITIALIZE CLOUD DB" IN ADMIN PORTAL, PASTE THE NEW ID HERE.
export const DB_ID = ''; 

const BASE_URL = 'https://jsonblob.com/api/jsonBlob';

export interface Inquiry {
  id: string;
  date: string;
  name: string;
  business: string;
  location: string;
  phone: string;
  volume: string;
  requirements: string;
}

export const StorageService = {
  /**
   * Fetches all inquiries from Cloud or LocalStorage
   */
  getInquiries: async (): Promise<Inquiry[]> => {
    if (!DB_ID) {
      console.warn('Storage: No DB_ID configured. Using LocalStorage.');
      return JSON.parse(localStorage.getItem('arka_inquiries') || '[]');
    }

    try {
      const response = await fetch(`${BASE_URL}/${DB_ID}`);
      if (!response.ok) throw new Error('Cloud DB not found');
      const data = await response.json();
      // Sync local backup
      localStorage.setItem('arka_inquiries', JSON.stringify(data));
      return data;
    } catch (error) {
      console.error('Storage: Cloud fetch failed, falling back to local.', error);
      return JSON.parse(localStorage.getItem('arka_inquiries') || '[]');
    }
  },

  /**
   * Saves a new inquiry to Cloud and LocalStorage
   */
  addInquiry: async (inquiry: Inquiry): Promise<void> => {
    // 1. Always save to local first (optimistic UI)
    const existing = JSON.parse(localStorage.getItem('arka_inquiries') || '[]');
    const updated = [inquiry, ...existing];
    localStorage.setItem('arka_inquiries', JSON.stringify(updated));

    // 2. Try to sync to cloud
    if (DB_ID) {
      try {
        // Fetch current cloud data first to avoid overwriting updates from others
        const currentCloudResponse = await fetch(`${BASE_URL}/${DB_ID}`);
        let currentCloudData: Inquiry[] = [];

        if (currentCloudResponse.ok) {
            currentCloudData = await currentCloudResponse.json();
        }

        const mergedData = [inquiry, ...currentCloudData];

        await fetch(`${BASE_URL}/${DB_ID}`, {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
          },
          body: JSON.stringify(mergedData),
        });
      } catch (error) {
        console.error('Storage: Failed to sync to cloud.', error);
        // We rely on local storage as backup
      }
    } else {
        console.warn('Storage: Data saved locally only. Configure DB_ID in storageService.ts to enable cloud sync.');
    }
  },

  /**
   * Clears all data
   */
  clearAll: async (): Promise<void> => {
    localStorage.removeItem('arka_inquiries');
    if (DB_ID) {
       await fetch(`${BASE_URL}/${DB_ID}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify([]),
        });
    }
  },

  /**
   * ADMIN UTILITY: Initialize a new JSONBlob
   * Returns the new Blob ID.
   */
  initializeCloudDB: async (): Promise<string> => {
    try {
      const response = await fetch(BASE_URL, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
        },
        body: JSON.stringify([]), // Initialize with empty array
      });

      const location = response.headers.get('Location');
      // Extract ID from Location header (e.g., https://jsonblob.com/api/jsonBlob/123 -> 123)
      const newId = location?.split('/').pop();
      return newId || '';
    } catch (e) {
      console.error(e);
      return '';
    }
  }
};

